using System;using System.IO;using Autodesk.Revit.DB;using SAUDICO.Federate.Core.Interfaces;using SAUDICO.Federate.Core.Models;using SAUDICO.Federate.Shared;namespace SAUDICO.Federate.Export;
public sealed class NwcExporter:INwcExporter { public ExportResult Export(Document d,View3D v,FederationJob j){var input=j.Model.FilePath;if(j.Model.Type==ModelType.ACC&&string.IsNullOrWhiteSpace(input))input=(j.Model.ModelGuid??"ACC-Model")+".rvt";var output=PathHelper.Output(input,j.OutputDirectory);j.OutputPath=output;if(File.Exists(output)&&!j.Overwrite)return ExportResult.Skip(output);Directory.CreateDirectory(j.OutputDirectory);if(File.Exists(output))File.Delete(output);using var o=ExportSettingsBuilder.Build(v.Id);d.Export(j.OutputDirectory,Path.GetFileNameWithoutExtension(output),o);return File.Exists(output)?ExportResult.Ok(output):ExportResult.Fail("Revit returned from export but the NWC file was not created.");} }
